function titleOf(c){return FRIENDLY_TITLES[c?.code]||c?.title||''}
function capTR(x){x=String(x||'').trim();return x?x.charAt(0).toLocaleUpperCase('tr-TR')+x.slice(1):''}
function labelTR(x){const k=String(x||'').trim();return KEY_LABELS[k]||capTR(k.replaceAll('_',' '))}
function friendlyPurpose(c){const t=titleOf(c),m=c?.module||'';
  const exact={
   'Nakit Yatırma':'Müşteri hesabına gişeden nakit yatırma işlemini güvenli biçimde başlatır ve işlem sonucunu kayda bağlar.',
   'Nakit Çekme':'Müşterinin hesabından gişeden nakit çekme işlemini limit, bakiye ve yetki kontrolleriyle yürütür.',
   'Kasa Açılışı':'Gün başında personelin kasasını açar, açılış tutarını ve kasa sorumluluğunu doğrular.',
   'Kasa Kapanışı':'Gün sonunda kasa bakiyesi ile sistem kayıtlarını karşılaştırır ve kapanış sonucunu kaydeder.',
   'Transfer Başlat':'Havale, EFT veya FAST işlemini kaynak hesap, alıcı, tutar ve açıklama bilgileriyle başlatır.',
   'Fatura Borç Sorgu':'Kurum ve abone bilgisi üzerinden ödenebilir borcu sorgular; ödeme yapılmadan önce tutarı doğrular.',
   'Kredi Başvuru Kuyruğu':'İşleme alınmayı bekleyen kredi başvurularını öncelik ve durum bilgileriyle listeler.',
   'Finansal Değerlendirme':'Kredi başvurusunun gelir, borçluluk, skor ve ödeme gücü bilgilerini karar öncesinde değerlendirir.',
   'Kart Servis Merkezi':'Aktif kartlarda kayıp/çalıntı, geçici kapatma, yenileme ve benzeri servis taleplerini yönetir.',
   'Teklif Başlat':'Müşterinin ihtiyacına göre sigorta ürünü seçerek teklif sürecini başlatır.',
   'Hasar İhbarı':'Poliçeye bağlı yeni hasar ihbarını olay ve belge bilgileriyle kayda alır.',
   'Müşteri 360°':'Müşterinin kimlik, hesap, kart, kredi, poliçe ve işlem bilgilerini tek profilde gösterir.',
   'Yeni Müşteri Sihirbazı':'Yeni müşteri kaydını kimlik, iletişim ve uyum kontrolleriyle adım adım oluşturur.',
   'Müşteri Kimlik ve Uyum Kontrolü':'Müşterinin kimlik doğrulama ve uyum durumunu kontrol eder; eksik veya riskli kayıtları gösterir.',
   'Merkezi İş Havuzu':'Müşteri, operasyon, onay ve eğitim kaynaklı bekleyen işleri tek listede toplar ve doğru personele yönlendirir.',
   'Onay Bekleyen İşler':'İkinci yetkili kontrolü gereken işlemleri risk, limit ve belge durumuyla birlikte gösterir.',
   'Mutabakat ve Fark Kontrolü':'Finansal kayıtlar ile ürün hareketleri arasındaki farkları karşılaştırır ve inceleme işi oluşturur.'
  }; if(exact[t])return exact[t];
  if(/Dashboard|Ana Sayfa|Genel Bakış/.test(t))return `${m} kapsamındaki önemli durumları, bekleyen işleri ve temel göstergeleri tek ekranda özetler.`;
  if(/Kuyruk|Havuz|Bekleyen|Liste|Arşiv|Geçmiş|Timeline|Takip|Durum/.test(t))return `${t} kayıtlarını anlaşılır bir listede görüntüler; seçilen kaydın ayrıntısına veya ilgili işleme geçmenizi sağlar.`;
  if(/Detay|Özet/.test(t))return `Seçilen kaydın ${t.toLocaleLowerCase('tr-TR')} bilgilerini tek ekranda görüntüler ve uygun sonraki işlemleri sunar.`;
  if(/Yönetim|Tanımla|Parametre|Matris|Ayar|Rol|Yetki|Kurumsal|Şube|Departman|Personel|Vekâlet|Tarife|Ürün/.test(t))return `${t} için kullanılan tanım ve kuralları yönetir. Değişiklikler yalnız yetkili kullanıcılar tarafından yapılır.`;
  if(/Rapor|Denetim|Audit|Mutabakat/.test(t))return `${t} kayıtlarını filtreleyerek incelemenizi ve gerekli kontrolleri yapmanızı sağlar.`;
  if(/Başvuru|Açılış|Ödeme|Transfer|Al|Sat|Kullandırım|Kapama|Yapılandırma|Zeyil|Yenileme|İptal|Fesih|İhbar|Tahsilat|Oluştur/.test(t))return `${t} işlemini gerekli müşteri/ürün bilgileri ve kontroller eşliğinde yürütür.`;
  return `${t} işlemini ${m} iş akışı içinde yürütmek için kullanılan ekrandır.`;
}
function actionText(a){return capTR(String(a||'').replaceAll('/',' / ').replace(/\s+/g,' '))}
function isInfoOnly(c){const t=titleOf(c);return /Dashboard|Ana Sayfa|Kuyruk|Havuz|Durumu|Durum$|Detay|Özet|Geçmiş|Timeline|Takip|Rapor|Denetim|Arşiv|Katalog|Panosu|Yetkilerim|Yardım|Hakkında/.test(t)||/Drill-down|filtre/i.test(c?.actions||'')}
function isCompositeField(f){return /[>↔→]|kartları|KPI|kartları|parametre kartları|başvuru\/tahsis|alış-satış|müşteri hizmetleri|gişe|transfer|kredi|sigorta|hasar|ticari|belge|kontrol/i.test(String(f||''))&&String(f||'').length>28}

