function renderLive(x){if(x==null)return '<div class="empty">Bu ekran için ayrı bir liste verisi bulunmuyor. İşlem düğmesi üzerinden ilgili kayıt ekranına geçebilirsiniz.</div>';if(!Array.isArray(x)&&typeof x==='object'){const arrays=Object.entries(x).filter(([,v])=>Array.isArray(v));if(arrays.length)return renderTable(arrays[0][1]);return `<div class="spec-grid">${Object.entries(x).slice(0,12).map(([k,v])=>spec(labelTR(k),typeof v==='object'?JSON.stringify(v):v)).join('')}</div>`}return renderTable(arr(x))}
let tableSequence=0;
const tableSortState=Object.create(null);
function renderTable(rows){
  rows=arr(rows).slice(0,30);
  if(!rows.length)return '<div class="empty">Kayıt bulunmuyor.</div>';
  const keys=[...new Set(rows.flatMap(o=>Object.keys(o||{})))].filter(k=>!/(password|token|hash|secret|raw)/i.test(k)).slice(0,7);
  const id=`ebs-table-${++tableSequence}`;
  tableSortState[id]={rows,keys,criteria:[]};
  return `<div class="table-wrap"><table class="data-table" id="${id}" data-sortable="true"><thead><tr>${keys.map(k=>`<th class="sortable" role="button" tabindex="0" data-sort-key="${esc(k)}" onclick="EBS.sortTable('${id}','${esc(k)}',event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();EBS.sortTable('${id}','${esc(k)}',event)}">${esc(labelTR(k))}<span class="sort-mark" aria-hidden="true"></span></th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr data-row-index="${i}">${keys.map(k=>`<td>${tableCell(r,k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
}
function sortValue(v){
  if(v==null)return {empty:true,text:''};
  if(typeof v==='number')return {number:v,text:String(v)};
  const text=String(v).trim();
  if(!text)return {empty:true,text:''};
  const numeric=text.replace(/\s/g,'').replace(/\.(?=\d{3}(?:\D|$))/g,'').replace(',','.');
  if(/^-?\d+(?:\.\d+)?$/.test(numeric))return {number:Number(numeric),text};
  const date=Date.parse(text);
  if(!Number.isNaN(date)&&/[T:/-]/.test(text))return {number:date,text};
  return {text:text.toLocaleLowerCase('tr-TR')};
}
function sortTable(id,key,event={}){
  const state=tableSortState[id], table=document.getElementById(id);
  if(!state||!table)return;
  const old=state.criteria.find(x=>x.key===key);
  const direction=old?old.direction==='asc'?'desc':'asc':'asc';
  if(event.ctrlKey){
    state.criteria=state.criteria.filter(x=>x.key!==key);
    state.criteria.push({key,direction});
  }else state.criteria=[{key,direction}];
  const indexed=state.rows.map((row,index)=>({row,index}));
  indexed.sort((a,b)=>{
    for(const criterion of state.criteria){
      const av=sortValue(a.row?.[criterion.key]),bv=sortValue(b.row?.[criterion.key]);
      let cmp=0;
      if(av.empty!==bv.empty)cmp=av.empty?1:-1;
      else if(av.number!==undefined&&bv.number!==undefined)cmp=av.number-bv.number;
      else cmp=av.text.localeCompare(bv.text,'tr-TR',{numeric:true,sensitivity:'base'});
      if(cmp)return criterion.direction==='asc'?cmp:-cmp;
    }
    return a.index-b.index;
  });
  const tbody=table.tBodies[0];
  tbody.innerHTML=indexed.map(({row,index})=>`<tr data-row-index="${index}">${state.keys.map(k=>`<td>${tableCell(row,k)}</td>`).join('')}</tr>`).join('');
  table.querySelectorAll('th[data-sort-key]').forEach(th=>{
    const c=state.criteria.find(x=>x.key===th.dataset.sortKey);
    th.classList.toggle('sorted',!!c);th.dataset.sortDirection=c?.direction||'';
    const marker=th.querySelector('.sort-mark');
    if(marker)marker.textContent=c?`${c.direction==='asc'?'▲':'▼'} ${state.criteria.indexOf(c)+1}`:'';
  });
}
function tableCell(row,key){if(key==='download_url'&&row?.[key])return `<a class="btn sm outline" href="${esc(row[key])}" target="_blank" rel="noopener">PDF indir</a>`;return esc(formatVal(row?.[key],key))}
function formatVal(v,k=''){if(v==null)return'';if(typeof v==='boolean')return v?'Evet':'Hayır';if(Array.isArray(v))return v.slice(0,3).map(x=>typeof x==='object'?JSON.stringify(x):x).join(', ');if(typeof v==='object')return JSON.stringify(v);let s=String(v);if(/status|durum/i.test(k)){const m={pending:'Bekliyor',open:'Açık',closed:'Kapalı',completed:'Tamamlandı',approved:'Onaylandı',rejected:'Reddedildi',active:'Aktif',inactive:'Pasif',new:'Yeni',in_progress:'İşlemde'};s=m[s.toLowerCase()]||s}return s}
async function loadCardHistory(code){const h=$('#cardHistory');if(!h)return;try{const x=await api(`/v3api/api/card/${encodeURIComponent(code)}`);const rows=arr(x);if(!rows.length)return;h.innerHTML=`<div class="section-title"><h4>v3.0 PRO İşlem Geçmişi</h4></div><div class="card">${renderTable(rows)}</div>`}catch{}}
async function cardAction(code,action,critical){const form=$('#cardForm');const operation=cardOperation[code];if(form&&!form.checkValidity()){form.reportValidity();return}const payload=operationPayload(code,form?formObj(form):{});try{if(!operation){throw Error('Bu ekranın gerçek işlem akışı henüz bağlanmadı; işlem başarılı gösterilmedi.')}const x=await realOperation(operation,payload);toast(`${action} tamamlandı. Referans: ${x.reference||'oluşturuldu'}`);loadCardHistory(code)}catch(e){toast(`Merkezi işlem: ${e.message}`,true)}}

async function renderWorklist(){S.page='PER-004';renderNav();setTitle('İşlerim','Bekleyen İşler / İş Listem');$('#contextText').textContent='Müşteri, senaryo, admin/personel ve onay kaynaklı merkezi iş havuzu';const root=$('#content');root.innerHTML='<div class="loading">Merkezi iş havuzu yükleniyor…</div>';const [rq,as,ap,us,cs,sc]=await Promise.all([api('/api/customer-requests').catch(()=>[]),api('/api/assignments').catch(()=>[]),api('/api/approvals').catch(()=>[]),api('/api/users').catch(()=>[]),api('/api/customers?limit=5000').catch(()=>[]),api('/api/scenarios').catch(()=>[])]);const users=arr(us),cust=arr(cs),scen=arr(sc);const uname=id=>(users.find(u=>String(u.id)===String(id))||{}).full_name||id||'Atama bekliyor';const cname=id=>{const c=cust.find(x=>String(x.id)===String(id));return c?`${c.name||''} ${c.surname||''}`.trim():id||'—'};let rows=[];for(const r of arr(rq))rows.push({source:'Müşteri Talebi',id:r.id,customer:cname(r.customer_id),title:r.request_type||r.title||'Müşteri işi',assigned:uname(r.assigned_user_id),status:r.status||'Bekliyor',page:requestPage(r)});for(const a of arr(as)){const s=scen.find(x=>String(x.id)===String(a.scenario_id));rows.push({source:'Senaryo',id:a.id,customer:cname(a.customer_id||s?.customer_id),title:s?.title||a.title||'Eğitim senaryosu',assigned:uname(a.user_id||a.assigned_user_id),status:a.status||'Bekliyor',page:'scenarios'})}for(const a of arr(ap))rows.push({source:'Onay / Sistem',id:a.id,customer:cname(a.customer_id),title:a.type||a.title||'Onay işi',assigned:uname(a.approver_id||a.assigned_user_id),status:a.status||'Bekliyor',page:'approvals'});root.innerHTML=`<div class="page-head"><div><h3>Bekleyen İşler / İş Listem</h3><p>Farklı kaynaklardan gelen işleri tek merkezi havuzda izleyin; işlem açılırken doğru müşteri ve modül bağlamı korunur.</p></div><button class="btn outline" onclick="EBS.openLegacy('requests')">Mevcut İş Kuyruğunu Aç</button></div><div class="grid cols-4">${kpi('Toplam',rows.length,'Görünen işler')}${kpi('Bekleyen',rows.filter(x=>/bek|yeni|pending/i.test(x.status)).length,'İşleme alınmadı')}${kpi('İşlemde',rows.filter(x=>/işlem|devam|progress/i.test(x.status)).length,'Devam eden')}${kpi('Tamamlanan',rows.filter(x=>/tamam|onay|closed/i.test(x.status)).length,'Kapanan')}</div><div class="section-title"><h4>İş Havuzu</h4></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Kaynak</th><th>Müşteri</th><th>İş / Görev</th><th>Atanan</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td><span class="status info">${esc(x.source)}</span></td><td>${esc(x.customer)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.assigned)}</td><td>${esc(x.status)}</td><td><button class="btn sm primary" onclick="EBS.openLegacy('${x.page}')">İşleme Al</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">İş bulunmuyor.</td></tr>'}</tbody></table></div></div>`}
function requestPage(r){const t=(r.request_type||'').toLocaleLowerCase('tr-TR');if(/sigorta|poliçe|prim|zeyil|teminat|lehtar|dain/.test(t))return'insurance';if(/hasar/.test(t))return'claims';if(/kart/.test(t))return'cards';if(/kredi/.test(t))return'loans';if(/fatura|otomatik ödeme/.test(t))return'payments';if(/transfer|eft|fast|havale|kolay adres|ödeme iste/.test(t))return'transfers';if(/hesap|mevduat|ekstre/.test(t))return'accounts';return'customers'}

async function renderCustomer360(){S.page='PER-005';renderNav();setTitle('Müşteri','Müşteri 360°');$('#contextText').textContent=S.selectedCustomer?`${S.selectedCustomer.name||''} ${S.selectedCustomer.surname||''}`:'Müşteri seçilmedi';const root=$('#content');const list=arr(await api('/api/customers?limit=5000').catch(()=>[]));root.innerHTML=`<div class="page-head"><div><h3>Müşteri 360°</h3><p>Müşterinin kimlik ve uyum, hesap, kredi, kart, poliçe ve işlem bilgilerini tek profilde görüntüleyin.</p></div><button class="btn outline" onclick="EBS.openLegacy('customers')">Mevcut Müşteri 360°</button></div><div class="card"><div class="card-body"><div class="form-grid"><label class="field full"><span>Müşteri ara</span><input id="custSearch" placeholder="Ad, soyad, TCKN veya müşteri no"></label></div><div id="custResults" class="list" style="margin-top:12px"></div></div></div><div id="cust360"></div>`;const inp=$('#custSearch');const draw=()=>{const q=inp.value.toLocaleLowerCase('tr-TR');const rows=list.filter(c=>(`${c.name||''} ${c.surname||''} ${c.tckn||''} ${c.customer_number||''}`).toLocaleLowerCase('tr-TR').includes(q)).slice(0,q?25:10);$('#custResults').innerHTML=rows.map(c=>`<div class="list-row"><div class="avatar">${initials((c.name||'')+' '+(c.surname||''))}</div><div class="grow"><strong>${esc(c.name)} ${esc(c.surname)}</strong><small>${esc(c.customer_number||c.id)} • ${esc(c.tckn||'')}</small></div><button class="btn sm primary" onclick="EBS.selectCustomer('${esc(c.id)}')">Aç</button></div>`).join('')};inp.oninput=draw;draw();if(S.selectedCustomer)selectCustomer(S.selectedCustomer.id)}
async function selectCustomer(id){try{const x=await api('/api/customers/'+encodeURIComponent(id));S.selectedCustomer=x.customer||x;window.__customer360Data=x;$('#contextText').textContent=`${S.selectedCustomer.name||''} ${S.selectedCustomer.surname||''}`;const c=S.selectedCustomer;$('#cust360').innerHTML=`<div class="section-title"><h4>Müşteri Profili</h4></div><div class="customer-summary"><div class="customer-profile"><div class="avatar">${initials((c.name||'')+' '+(c.surname||''))}</div><h4>${esc(c.name)} ${esc(c.surname)}</h4><p>Müşteri No: ${esc(c.customer_number||c.id)}<br>T.C. Kimlik No: ${esc(c.tckn||'—')}<br>Telefon: ${esc(c.phone||'—')}</p><span class="status info">Kimlik / Uyum: ${esc(c.kyc_status||'—')}</span></div><div class="customer-products">${kpi('Hesap',arr(x.accounts).length,'Ürün')}${kpi('Kredi',arr(x.loans).length,'Ürün')}${kpi('Kart',arr(x.cards).length,'Ürün')}${kpi('Poliçe',arr(x.policies).length,'Ürün')}</div></div><div class="section-title"><h4>Ürünler ve Hareketler</h4><div class="actions"><button class="btn sm primary" onclick="EBS.go('accounts-hub')">Hesap İşlemi</button><button class="btn sm outline" onclick="EBS.go('loans-hub')">Kredi İşlemi</button><button class="btn sm outline" onclick="EBS.go('cards-hub')">Kart İşlemi</button><button class="btn sm outline" onclick="EBS.go('insurance-hub')">Poliçe İşlemi</button></div></div><div class="card"><div class="card-body"><div class="tabs"><div class="tab active" data-c360="accounts" onclick="EBS.customer360Tab('accounts')">Hesaplar</div><div class="tab" data-c360="cards" onclick="EBS.customer360Tab('cards')">Kartlar</div><div class="tab" data-c360="loans" onclick="EBS.customer360Tab('loans')">Krediler</div><div class="tab" data-c360="policies" onclick="EBS.customer360Tab('policies')">Poliçeler</div><div class="tab" data-c360="claims" onclick="EBS.customer360Tab('claims')">Hasarlar</div></div><div id="customer360Table"></div></div></div>`;customer360Tab('accounts')}catch(e){toast(e.message,true)}}
function customer360Tab(kind){const x=window.__customer360Data||{};$$('[data-c360]').forEach(t=>t.classList.toggle('active',t.dataset.c360===kind));const labels={accounts:'Hesap',cards:'Kart',loans:'Kredi',policies:'Poliçe',claims:'Hasar'};let rows=arr(x[kind]);if(kind==='claims'&&!rows.length)rows=arr(x.claim_files||x.claims);const host=$('#customer360Table');if(host)host.innerHTML=`<div class="section-title compact"><h4>${labels[kind]||'Kayıt'} Kayıtları</h4></div>${renderTable(rows)}`}


async function renderScenarioAssignment(){S.page='AES-018';renderNav();setTitle('Eğitim','Senaryo / Görev Toplu Atama');$('#contextText').textContent='Senaryoyu kullanıcı, rol, grup veya tüm kullanıcılara görev olarak atayın';const root=$('#content');root.innerHTML='<div class="loading">Senaryo ve hedefler yükleniyor…</div>';const [oldSc,oldUs,ro,gr,oldAs,vsc,vas,trainees]=await Promise.all([api('/api/scenarios').catch(()=>[]),api('/api/users').catch(()=>[]),api('/api/roles').catch(()=>[]),api('/api/user-groups').catch(()=>[]),api('/api/assignments').catch(()=>[]),v3query('training-scenarios').catch(()=>[]),v3query('training-assignments').catch(()=>[]),v3query('training-trainees').catch(()=>[])]);const sc=arr(vsc).length?arr(vsc):arr(oldSc),as=arr(vas).length?arr(vas):arr(oldAs),us=arr(trainees).length?arr(trainees):arr(oldUs);window.__scenarioData={sc,us,ro:arr(ro),gr:arr(gr)};root.innerHTML=`<div class="page-head"><div><h3>Senaryo / Görev Toplu Atama</h3><p>Senaryoyu tek veya birden çok kullanıcıya, role, tanımlı gruba ya da tüm kullanıcılarına görev olarak atayın.</p></div><button class="btn outline" onclick="EBS.openLegacy('scenarios')">Senaryo Kataloğunu Aç</button></div><div class="grid cols-2"><div class="card"><div class="card-head"><h4>Yeni Atama</h4><span class="status info">Eğitim Görevi</span></div><div class="card-body"><form id="scenarioBulk" class="form-grid"><label class="field full"><span>Senaryo</span><select name="scenario_id">${arr(sc).map(s=>`<option value="${esc(s.id)}">${esc(s.title||s.id)}</option>`).join('')}</select></label><label class="field"><span>Atama Tipi</span><select name="assign_type" id="assignType"><option value="user">Tek / çoklu kullanıcı</option><option value="role">Rol</option><option value="group">Tanımlı grup</option><option value="all">Tüm kullanıcılar</option></select></label><label class="field"><span>Başlangıç zamanı</span><input name="start_time" type="datetime-local"></label><div id="assignTarget" class="field full"></div><label class="field full"><span>Görev mesajı</span><textarea name="message" rows="4" placeholder="Atama ile birlikte ekran görev bildirimi gönderilir."></textarea></label></form><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="EBS.submitScenarioBulk()">Ata ve Talimat Gönder</button></div></div></div><div class="card"><div class="card-head"><h4>Mevcut Atamalar</h4><span class="status">${arr(as).length}</span></div><div class="card-body">${renderTable(arr(as))}</div></div></div>`;$('#assignType').onchange=renderAssignTarget;renderAssignTarget()}
function renderAssignTarget(){const t=$('#assignType')?.value,d=window.__scenarioData;if(!d)return;const box=$('#assignTarget');if(t==='user')box.innerHTML=`<span>Kullanıcılar</span><div class="list" style="max-height:220px;overflow:auto">${d.us.filter(u=>u.active!==false&&u.role!=='customer').map(u=>`<label class="list-row"><input class="bulkUser" type="checkbox" value="${esc(u.id)}"> <span><strong>${esc(u.full_name||u.username)}</strong><small>${esc(u.username)} • ${esc(u.role)}</small></span></label>`).join('')}</div>`;else if(t==='role')box.innerHTML=`<span>Rol</span><select id="bulkRole">${d.ro.filter(r=>r.active!==false&&r.id!=='customer').map(r=>`<option value="${esc(r.id)}">${esc(r.name||r.id)}</option>`).join('')}</select>`;else if(t==='group')box.innerHTML=`<span>Grup</span><select id="bulkGroup">${d.gr.map(g=>`<option value="${esc(g.id)}">${esc(g.name||g.id)}</option>`).join('')}</select>`;else box.innerHTML='<div class="alert warning">Tüm aktif operasyon kullanıcılarına atanacaktır.</div>'}
async function submitScenarioBulk(){const f=$('#scenarioBulk'),d=formObj(f),type=d.assign_type;try{if(S.v3token){let targets=[];if(type==='user')targets=$$('.bulkUser:checked').map(x=>x.value);else if(type==='all')targets=window.__scenarioData.us.map(x=>x.username);else if(type==='role')targets=window.__scenarioData.us.filter(x=>String(x.role_id||x.role||'').toLowerCase()===String($('#bulkRole').value||'').toLowerCase()).map(x=>x.username);else if(type==='group')throw Error('Eğitim grubu eşlemesi bu sürümde tanımlanmadan atama yapılmadı.');if(!targets.length)throw Error('En az bir personel seçilmelidir.');const scenario=window.__scenarioData.sc.find(x=>String(x.id)===String(d.scenario_id));if(!scenario)throw Error('Senaryo bulunamadı.');for(const username of targets)await realOperation('training.assign',{scenario_id:String(scenario.id),trainee_username:username,due_at:d.start_time||''});toast(`${targets.length} personele gerçek eğitim ataması yapıldı.`);renderScenarioAssignment();return}const body={user_ids:[],role_ids:[],group_ids:[],all:type==='all',message:d.message||''};if(type==='user')body.user_ids=$$('.bulkUser:checked').map(x=>x.value);if(type==='role')body.role_ids=[$('#bulkRole').value];if(type==='group')body.group_ids=[$('#bulkGroup').value];const x=await post(`/api/scenarios/${encodeURIComponent(d.scenario_id)}/assign-bulk`,body);toast(`${x.assigned??'Seçilen'} kullanıcıya görev atandı.`);renderScenarioAssignment()}catch(e){toast(e.message,true)}}

async function renderMessages(){S.page='AES-029';renderNav();setTitle('İletişim','Mesaj ve Görev Merkezi');$('#contextText').textContent='Mesaj ve görevleri ilgili kullanıcıya veya gruba yönlendirin';const [ms,us,ro,gr,tp]=await Promise.all([api('/api/messages').catch(()=>[]),api('/api/users').catch(()=>[]),api('/api/roles').catch(()=>[]),api('/api/user-groups').catch(()=>[]),api('/api/message-templates').catch(()=>[])]);window.__msg={us:arr(us),ro:arr(ro),gr:arr(gr),tp:arr(tp)};$('#content').innerHTML=`<div class="page-head"><div><h3>İç Mesaj & Görev Merkezi</h3><p>Mesaj, görev, ekran bildirimi, rol/grup bazlı toplu dağıtım ve geçmiş tek merkezde yönetilir.</p></div><button class="btn outline" onclick="EBS.openLegacy('messages')">Mevcut Mesajlar / Görevler</button></div><div class="grid cols-2"><div class="card"><div class="card-head"><h4>Mesaj / Görev Gönder</h4></div><div class="card-body"><form id="msgForm" class="form-grid"><label class="field"><span>Tür</span><select name="kind"><option>Görev</option><option>Mesaj</option></select></label><label class="field"><span>Alıcı Tipi</span><select name="target_type" id="msgTargetType"><option value="user">Kullanıcı</option><option value="role">Rol</option><option value="group">Grup</option><option value="all">Tümü</option></select></label><label class="field full"><span>Alıcı</span><select name="target_id" id="msgTarget"></select></label><label class="field full"><span>Konu</span><input name="subject"></label><label class="field full"><span>Mesaj</span><textarea name="message" rows="5"></textarea></label><label class="field"><span>İlgili modül</span><select name="module"><option value="customers">Müşteri Hizmetleri</option><option value="teller">Gişe ve Kasa</option><option value="transfers">Para Transferleri</option><option value="loans">Krediler</option><option value="cards">Kartlar</option><option value="insurance">Sigortacılık</option><option value="claims">Hasar</option><option value="documents">Belgeler</option></select></label><label class="field"><span>Ekran Bildirimi</span><select name="popup"><option value="true">Göster</option><option value="false">Gösterme</option></select></label></form><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="EBS.sendMessage()">Mesaj / Görev Gönder</button></div></div></div><div class="card"><div class="card-head"><h4>Mesaj Geçmişi</h4><span class="status">${arr(ms).length}</span></div><div class="card-body">${renderTable(arr(ms))}</div></div></div>`;$('#msgTargetType').onchange=renderMsgTarget;renderMsgTarget()}
function renderMsgTarget(){const d=window.__msg,t=$('#msgTargetType').value,s=$('#msgTarget');if(t==='user')s.innerHTML=d.us.filter(x=>x.active!==false).map(x=>`<option value="${esc(x.id)}">${esc(x.full_name||x.username)}</option>`).join('');else if(t==='role')s.innerHTML=d.ro.map(x=>`<option value="${esc(x.id)}">${esc(x.name||x.id)}</option>`).join('');else if(t==='group')s.innerHTML=d.gr.map(x=>`<option value="${esc(x.id)}">${esc(x.name||x.id)}</option>`).join('');else s.innerHTML='<option value="all">Tüm kullanıcılar</option>'}
async function sendMessage(){const d=formObj($('#msgForm'));const body={kind:d.kind,subject:d.subject,message:d.message,popup:d.popup==='true',module:d.module};if(d.target_type==='user')body.user_id=d.target_id;else if(d.target_type==='role')body.role_id=d.target_id;else if(d.target_type==='group')body.group_id=d.target_id;else body.all=true;try{await post('/api/messages',body);toast('Mesaj / görev gönderildi.');renderMessages()}catch(e){toast(e.message,true)}}

